static class Program {
 static int checks;
 static void Check(bool value,string name){if(!value)throw new Exception(name);checks++;}
 [STAThread] static int Main(){try{Replay().GetAwaiter().GetResult();Lifecycle().GetAwaiter().GetResult();Integration().GetAwaiter().GetResult();Ui();Console.WriteLine($"ImageBuffer.PluginChecks: {checks} passed");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
 static async Task Replay(){using var evidence=JsonDocument.Parse(File.ReadAllText("docs/plugins/image-buffer-evidence.json"));var plugin=new ImageBufferPlugin();using var scope=new ModuleExecutionScope();var inputs=new Dictionary<string,PortValue>();
  Check(plugin.Descriptor.Parameters.Count==0&&plugin.Descriptor.Inputs.Count==3&&plugin.Descriptor.Outputs.Count==62,"native declaration flattened");
  foreach(var row in evidence.RootElement.GetProperty("rows").EnumerateArray().Where(r=>r.TryGetProperty("images",out _))){string phase=row.GetProperty("phase").GetString()!;if(phase=="reloaded-cache-empty"){scope.RemoveNode(ImageBufferPlugin.Id,"buffer");inputs.Clear();}int value=row.GetProperty("value").GetInt32(),w=row.GetProperty("width").GetInt32(),h=row.GetProperty("height").GetInt32(),channels=row.GetProperty("channels").GetInt32();byte[] bytes=Enumerable.Range(0,w*h*channels).Select(i=>(byte)((value+i)%256)).ToArray();int requested=row.TryGetProperty("requestedFormat",out var requestedValue)?requestedValue.GetInt32():0;int format=requested==0?(channels==1?17301505:35127316):row.TryGetProperty("rawFormat",out var raw)&&raw.GetBoolean()?requested:requested is 17301505 or 35127316 or 35127329?requested:17301505;IImageData image=requested!=0?new RawImage(w,h,(ImagePixelFormat)format,bytes):channels==1?new GrayImage(w,h,bytes):new RgbImage(w,h,bytes);inputs["InputImage"]=PortValue.Image(image);foreach(string key in new[]{"flag","count"})if(row.GetProperty(key).ValueKind!=JsonValueKind.Null)inputs[key=="flag"?"RefreshFlag":"BufferCount"]=PortValue.Integer(row.GetProperty(key).GetInt32());
   var result=await plugin.CreateRuntime().ExecuteAsync(new("buffer",Environment.CurrentDirectory,inputs,new Dictionary<string,JsonElement>()){Scope=scope},default);Check(result.NativeErrorCode==row.GetProperty("code").GetUInt32(),phase+" native code");Check(result.Outputs["ModuStatus"].As<long>()==row.GetProperty("status").GetInt32(),phase+" status");
   foreach(var slot in row.GetProperty("images").EnumerateArray()){string prefix="OutImage"+slot.GetProperty("slot").GetInt32();int len=slot.GetProperty("length").GetInt32();Check(result.Outputs.ContainsKey(prefix+"Image")== (len>0),phase+" presence "+prefix);if(len==0)continue;var actual=result.Outputs[prefix+"Image"].As<IImageData>();Check(actual.Width==slot.GetProperty("width").GetInt32()&&actual.Height==slot.GetProperty("height").GetInt32()&&(int)actual.Format==slot.GetProperty("format").GetInt32(),phase+" dimensions/format");Check(actual.Pixels.Length==len&&Convert.ToHexString(SHA256.HashData(actual.Pixels)).ToLowerInvariant()==slot.GetProperty("sha256").GetString(),phase+" every pixel");}
  }
 }
 static async Task Lifecycle(){var plugin=new ImageBufferPlugin();var p=new Dictionary<string,JsonElement>();var inputs=new Dictionary<string,PortValue>();using var scope=new ModuleExecutionScope();
  ValueTask<ModuleResult> Run(string id="a",ModuleExecutionScope? owner=null)=>plugin.CreateRuntime().ExecuteAsync(new(id,Environment.CurrentDirectory,inputs,p){Scope=owner??scope},default);
  Check((await Run()).NativeErrorCode==0xe0000510,"missing image fails on refresh");inputs["RefreshFlag"]=PortValue.Integer(0);Check((await Run()).Status==ModuleStatus.Success,"empty hold without image");inputs["InputImage"]=PortValue.Image(new GrayImage(2,2,new byte[]{1,2,3,4}));inputs["RefreshFlag"]=PortValue.Integer(1);var first=await Run();Check(first.Outputs["OutImage0Image"].As<IImageData>().Pixels.SequenceEqual(new byte[]{1,2,3,4}),"deep copy");inputs["RefreshFlag"]=PortValue.Integer(0);inputs["BufferCount"]=PortValue.Integer(0);Check((await Run()).Outputs.ContainsKey("OutImage0Image"),"shrinking hold keeps cache");Check(!(await Run("b")).Outputs.ContainsKey("OutImage0Image"),"node isolation");using(var other=new ModuleExecutionScope())Check(!(await Run(owner:other)).Outputs.ContainsKey("OutImage0Image"),"session isolation");inputs["BufferCount"]=PortValue.Integer(-1);Check((await Run()).NativeErrorCode==0xe000031c,"count checked even while held");inputs["BufferCount"]=PortValue.Integer(15);Check((await Run()).Outputs.ContainsKey("OutImage0Image"),"invalid count preserves cache");scope.RemoveNode(ImageBufferPlugin.Id,"a");Check(!(await Run()).Outputs.ContainsKey("OutImage0Image"),"removing node clears cache");
  inputs["RefreshFlag"]=PortValue.Integer(1);for(int i=0;i<20;i++){inputs["InputImage"]=PortValue.Image(new GrayImage(1,1,new byte[]{(byte)i}));var r=await Run();Check(r.Outputs.Values.Count(v=>DataKinds.IsImage(v.Kind))==Math.Min(i+1,15),"capacity");Check(r.Outputs["OutImage0Image"].As<IImageData>().Pixels[0]==Math.Max(0,i-14),"FIFO full capacity");}inputs["BufferCount"]=PortValue.Integer(0);Check((await Run()).Outputs.Count==2,"zero clears on refresh");
  inputs["BufferCount"]=PortValue.Integer(15);using var cancelled=new CancellationTokenSource();cancelled.Cancel();try{await plugin.CreateRuntime().ExecuteAsync(new("a",Environment.CurrentDirectory,inputs,p){Scope=scope},cancelled.Token);throw new Exception("Cancellation ignored");}catch(OperationCanceledException){checks++;}inputs["RefreshFlag"]=PortValue.Integer(0);Check((await Run()).Outputs.Count==2,"cancel cannot append");
  var modules=new ModuleRegistry();var host=new ToolPluginRegistry();host.Register(plugin,modules);var node=new NodeDocument("held",ImageBufferPlugin.Id,"1.0.0","缓存图像",p);var flow=new ProcedureDocument("f","流程",[node],[],[]);
 }
 static IEnumerable<DependencyObject> Descendants(DependencyObject root){for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var child=VisualTreeHelper.GetChild(root,i);yield return child;foreach(var item in Descendants(child))yield return item;}}
 sealed class Source:IModule {
  public static int Runs;
  public ModuleDescriptor Descriptor{get;}=new("test.source","1","源",[],[new("Image",DataKind.Image)],[]);
  public ValueTask<ModuleResult> ExecuteAsync(ModuleExecutionContext c,CancellationToken token){Runs++;return ValueTask.FromResult(new ModuleResult(ModuleStatus.Success,new Dictionary<string,PortValue>{{"Image",PortValue.Image(new GrayImage(2,2,new byte[]{(byte)Runs,2,3,4}))}}));}
 }
 static async Task Integration(){var plugin=new ImageBufferPlugin();var registry=new ModuleRegistry();registry.Register(plugin.Descriptor,plugin.CreateRuntime);var source=new Source();registry.Register(source.Descriptor,()=>new Source());var node=new NodeDocument("buffer",ImageBufferPlugin.Id,"1.0.0","缓存图像",new());var from=new NodeDocument("source","test.source","1","源",new());var flow=new ProcedureDocument("flow","流程",[from,node],[new("source","Image","buffer","InputImage")],[new("source","buffer")]){Configuration=new(){Subscriptions=[new("buffer","BufferCount",false,new(WorkflowSourceKind.IntegerConstant,"2"))]}};
  using var scope=new ModuleExecutionScope();var executor=new GraphExecutor(registry);Check(GraphValidator.Validate(flow,registry).IsValid,"constant input validation");for(int i=0;i<4;i++){var run=await executor.RunAsync(flow,Environment.CurrentDirectory,scope:scope);Check(run.Status==SessionStatus.Success,"graph execution");Check(run.Nodes.Last().Outputs.Keys.Count(k=>k.EndsWith("Image"))==Math.Min(i+1,2),"constant count execution");}
  string path=Path.GetFullPath("analysis/full-audit/image-buffer/roundtrip.vmx.json");SolutionStore.Save(path,new(1,"owned","缓存验证",[flow],[]));var restored=SolutionStore.Load(path);Check(restored.Procedures.Single().Configuration.Subscriptions.Single().Source.Kind==WorkflowSourceKind.IntegerConstant,"constant persists");using(var fresh=new ModuleExecutionScope()){var run=await executor.RunAsync(restored.Procedures.Single(),Environment.CurrentDirectory,scope:fresh);Check(run.Nodes.Last().Outputs.Keys.Count(k=>k.EndsWith("Image"))==1,"cache not serialized");}
  var held=flow with{Configuration=flow.Configuration with{Subscriptions=flow.Configuration.Subscriptions.Append(new("buffer","RefreshFlag",false,new(WorkflowSourceKind.IntegerConstant,"0"))).ToArray()}};var before=await executor.RunAsync(held,Environment.CurrentDirectory,scope:scope);Check(before.Nodes.Last().Outputs["OutImage1Image"].As<IImageData>().Pixels[0]==4,"hold ignores new graph source");
  foreach(string literal in new[]{"2147483648","1.5","abc"}){var bad=flow with{Configuration=new(){Subscriptions=[new("buffer","BufferCount",false,new(WorkflowSourceKind.IntegerConstant,literal))]}};Check(!GraphValidator.Validate(bad,registry).IsValid,"invalid integer literal rejected");}
  var wrong=flow with{Configuration=new(){Subscriptions=[new("buffer","InputImage",false,new(WorkflowSourceKind.IntegerConstant,"1"))]}};Check(!GraphValidator.Validate(wrong,registry).IsValid,"integer cannot bind image");
 }
 static void Ui(){
  SynchronizationContext.SetSynchronizationContext(new System.Windows.Threading.DispatcherSynchronizationContext(System.Windows.Threading.Dispatcher.CurrentDispatcher));
  foreach(var mode in new[]{ToolEditorMode.Desktop,ToolEditorMode.SdkEmbedded}){
   var plugin=new ImageBufferPlugin();var node=new NodeDocument("ui",ImageBufferPlugin.Id,"1.0.0","缓存图像",new());var calls=new List<string>();var literals=new Dictionary<string,int>();int runs=0;
   var window=plugin.CreateWpfEditor(new(node,Environment.CurrentDirectory,_=>{},_=>{runs++;return Task.FromResult(new NodeRunRecord("ui",NodeRunStatus.Success,new Dictionary<string,PortValue>(),0));}){Mode=mode,DisplayIndex=4,SubscriptionLabel=(port,param)=>literals.TryGetValue(port,out int value)?value.ToString():calls.Contains(port)?"变量."+port:"",SetInputInteger=(port,value)=>{if(value.HasValue)literals[port]=value.Value;else literals.Remove(port);},PickSubscription=(owner,port,param,kind)=>{Check(!param,"subscriptions are inputs");Check(kind==(port=="InputImage"?DataKind.Image:DataKind.Integer),"subscription types");calls.Add(port);literals.Remove(port);return "变量."+port;}});
   window.Left=-30000;window.Top=-30000;window.ShowActivated=false;window.ShowInTaskbar=false;window.Show();window.UpdateLayout();var labels=Descendants(window).OfType<TextBlock>().Select(t=>t.Text).ToArray();Check(labels.Contains("缓存设置")&&labels.Contains("缓存使能")&&labels.Contains("缓存数量"),"original labels");Check(labels.Contains("输入源")&&labels.Contains("图像输入"),"original shared group");
   var boxes=Descendants(window).OfType<System.Windows.Controls.TextBox>().ToDictionary(t=>t.Name);
   void Enter(string value){var text=boxes["ValueBufferCount"];text.Text=value;text.RaiseEvent(new System.Windows.Input.KeyEventArgs(System.Windows.Input.Keyboard.PrimaryDevice,PresentationSource.FromVisual(window)!,Environment.TickCount,System.Windows.Input.Key.Enter){RoutedEvent=System.Windows.Input.Keyboard.KeyDownEvent});}
   Enter("3");Check(literals["BufferCount"]==3,"integer constant commit");Enter("invalid");Check(literals["BufferCount"]==3&&boxes["ValueBufferCount"].Text=="3","invalid integer restored");Enter("");Check(!literals.ContainsKey("BufferCount"),"clear restores native default");
   var buttons=Descendants(window).OfType<System.Windows.Controls.Button>().ToArray();foreach(var button in buttons.Where(b=>b.Name.StartsWith("Subscribe")))button.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));Check(calls.Count==3,"all subscriptions wired");Check(boxes["ValueBufferCount"].Text=="变量.BufferCount","subscription label updated");
   var once=buttons.Single(b=>b.Name=="ExecuteBuffer");once.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));Check(runs==1,"execute uses run callback");var loop=buttons.Single(b=>b.Name=="ContinuousBuffer");loop.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));Check(runs==2&&loop.Content.ToString()=="停止","continuous executes and exposes stop");loop.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));Check(loop.Content.ToString()=="连续执行","stop ends repeated execution");
   window.UpdateLayout();var bitmap=new RenderTargetBitmap(420,500,96,96,PixelFormats.Pbgra32);bitmap.Render(window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));Directory.CreateDirectory("analysis/full-audit/image-buffer");using(var stream=File.Create("analysis/full-audit/image-buffer/independent-"+mode+".png"))encoder.Save(stream);buttons.Single(b=>b.Name=="ConfirmBuffer").RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));Check(!window.IsVisible,"confirm closes editor and stops scheduling");
  }
  var planar=new RawImage(2,1,(ImagePixelFormat)0x02180021,new byte[]{1,2,10,20,100,200});Check(ImagePreview.Packed(planar)!.Pixels.SequenceEqual(new byte[]{1,10,100,2,20,200}),"planar preview is separate from cached bytes");Check(planar.Pixels.SequenceEqual(new byte[]{1,2,10,20,100,200}),"preview preserves payload");Check(ImagePreview.Packed(new RawImage(1,1,(ImagePixelFormat)12345,new byte[]{1})) is null,"opaque format has no misleading preview");
 }
